import{_ as r,a as o}from"./chunks/286b1b0289712cdbbf2e.B4AIkJ98.js";import{_ as p,C as l,o as n,c as i,j as a,a as s,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"如何最终不再在乎别人的看法","description":"","frontmatter":{"title":"如何最终不再在乎别人的看法","originalTitle":"How To Finally Stop Caring What Other People Think","date":"2022-05-21","originalUrl":"https://thedankoe.com/letters/how-to-finally-stop-caring-what-other-people-think/","minutes":10,"sourceHash":"c485c9345454b0e689b6530d3fa203fa23732c03279bd7d58e2c8b6aa193a349","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-finally-stop-caring-what-other-people-think/"}]]},"headers":[],"relativePath":"letters/how-to-finally-stop-caring-what-other-people-think.md","filePath":"letters/how-to-finally-stop-caring-what-other-people-think.md"}'),d={name:"letters/how-to-finally-stop-caring-what-other-people-think.md"};function m(f,e,u,b,k,g){const t=l("ArticleMeta");return n(),i("div",null,[e[0]||(e[0]=a("h1",{id:"如何最终不再在乎别人的看法",tabindex:"-1"},[s("如何最终不再在乎别人的看法 "),a("a",{class:"header-anchor",href:"#如何最终不再在乎别人的看法","aria-label":'Permalink to "如何最终不再在乎别人的看法"'},"​")],-1)),h(t),e[1]||(e[1]=c('<p><a href="https://www.youtube.com/embed/Sl0AvS8WJ54?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/0kMCOBqwgApt8m1QgAObvj?si=ac2ae5bf13bb4840&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>小时候，电子游戏让我着迷。我记得我曾哀求妈妈给我买第一款“M级（成人级）”游戏《使命召唤：现代战争》（Call Of Duty Modern Warfare），因为我所有的朋友都在玩。她妥协了。我每天晚上狂喝胡椒博士（Dr. Pepper），在游戏准备大厅里对着其他小孩破口大骂，熬到凌晨两点才睡——然后就在上学前一小时爬起来，只为了再玩一局。</p><p>你可以说我上瘾了。甚至可以说，我是<em>痴迷</em>其中。</p><p>随着时间的推移，我组装了自己的第一台电脑。这个有趣的小爱好为我打开了一个全新的游戏世界。《英雄联盟》（League Of Legends）和《魔兽世界》（World Of Warcraft）成了我的最爱。在大概5年的时间里，我每天晚上都死死盯着屏幕（当然是在我去过健身房之后！这是我给自己的“奖励”）。</p><p>我不会成为那种劝你戒掉电子游戏的人。我现在过得挺好——而且我认为玩游戏的那段时光对我的生活来说是净收益。虽然我现在不玩了——但从我作为玩家的岁月里，可以提取出很多经验教训。</p><h2 id="为什么我们会变得痴迷" tabindex="-1">为什么我们会变得痴迷 <a class="header-anchor" href="#为什么我们会变得痴迷" aria-label="Permalink to &quot;为什么我们会变得痴迷&quot;">​</a></h2><p>为什么我们会对游戏如此痴迷？有几个原因。</p><p>大脑渴望秩序。它厌恶混乱。人类追求<a href="https://shop.thedankoe.com/planner" target="_blank" rel="noreferrer">目标层级</a>以维持内心的秩序。这可能是有意识的，也可能是无意识的；可能是被分配的，也可能是自己创造的。领导者和操纵者都深知这一点。企业职场有分配给你的每日目标、每周目标、年度目标和个人目标。这减少了你每天需要做什么的不确定性。文化和政治也有目标。政治领袖让你支持他们对世界的愿景，清晰地阐述他们将如何实现这一愿景（目标），然后向你拉选票。</p><p>想让这招更具杀伤力吗？用讲故事的方式。正如我们在之前的信中所讨论的，<a href="https://thedankoe.com/how-to-copy-your-way-to-success-instead-of-mediocrity/" target="_blank" rel="noreferrer">所有的理解都是隐喻性的</a>。基于故事的。一件事必须在另一件事之前发生。这个词必须在这个词之前出现，这个词对你来说才有意义。一个目标必须在另一个目标之前实现，它才有意义。只有在理解了人们谈论的视角——那个隐喻世界——之后，剩下的内容才说得通。也就是说，你需要理解故事的背景设定。接下来是什么？情节的发展。然后是主角与反派的交锋。最后是情节的缓和与大结局。</p><p>当我们不理解某件事时，我们的大脑就会填补故事的空白。这被称为假设。你手里没有这块拼图，所以你就根据自己的经验去想象它。根据你被写入的程序去想象。这是危险的，通常也是无用的。这只会分散你的注意力，让你偏离对你真正重要的事情。</p><p>这就引发了痴迷。当某件事让我们觉得莫名其妙时——我们就会产生弄懂它的冲动。为了弄懂它，我们需要揭开故事的其余部分。我们想要理解前因、后果以及中间发生的一切。</p><h2 id="转移痴迷——获得极大成功且不再在乎别人看法的关键" tabindex="-1">转移痴迷——获得极大成功且不再在乎别人看法的关键 <a class="header-anchor" href="#转移痴迷——获得极大成功且不再在乎别人看法的关键" aria-label="Permalink to &quot;转移痴迷——获得极大成功且不再在乎别人看法的关键&quot;">​</a></h2><p>阿诺德（Arnold）曾很痴迷。沃尔特·迪士尼（Walt Disney）曾很痴迷。埃隆（Elon）<em>现在</em>很痴迷。乔·罗根（Joe Rogan）<em>现在</em>很痴迷。他们在乎别人怎么看他们吗？他们在乎别人说他们疯了吗？不在乎。他们极度专注地去实现一个他们充满热情的想法，根本不管短期回报如何。</p><p>对我来说，痴迷标志着一种有序的意识。一种难以被分散注意力的清晰状态。有人称之为心流（flow），有人称之为活在当下。我们可以整天给它贴标签，但在现实中——这感觉就是很爽。</p><blockquote><p>“为了做出原创性的贡献，你必须对某件事有着非理性的痴迷。” —— 纳瓦尔·拉维坎特（Naval Ravikant）</p></blockquote><p>你想了解什么故事？什么是能激发你兴奋感的冰山一角？深挖下去。这就是大多数人犯错的地方。他们不允许自己潜入这座充满机会的冰山。</p><p>举个最近的例子。我偶然看到了艾伦·瓦茨（Alan Watts）一个分为两部分的讲座，名叫《你是神》（You Are God）。这激发了我的兴奋。这是一个新颖的视角，抓住了我的眼球。什么鬼？我是神？这怎么可能？所以我没有对这个新想法封闭心扉（就像大多数处于<a href="https://thedankoe.com/why-choosing-a-niche-is-stupid-for-intelligent-people/" target="_blank" rel="noreferrer">前理性或理性阶段</a>发展的人会做的那样），而是剖析了它。我必须拼凑出这个故事。是什么让他说出这样的话？横向和纵向的提问。从那以后，我把这个讲座听了10多遍，在我消费的其他内容（比如 Actualized.org 上关于神性意识的讲座）中注意到了他的教导，能够将它们联系起来（模式识别），并且至少获得了一定程度的理解。</p><p>我依然没有完全理解，但这就是乐趣所在，不是吗？我们难道真的能探索完我们所痴迷的那座冰山的每一寸角落吗？</p><p>好了，所有关于痴迷的探讨都很棒，但我们如何朝着正确的方向去痴迷？一个能通往极大成功的方向？</p><blockquote><p>“追随你的痴迷，直到一个问题开始浮现，一个影响尽可能多人的、极具分量和挑战性的问题，一个让你不顾一切想要解决、即使拼死也要尝试的问题。” —— 贾斯汀·马斯克（Justine Musk）</p></blockquote><p>在我看来，痴迷与心流状态有关。那些自然而然对事物产生痴迷的人，随着时间的推移进入了心流状态，并将这种状态贴上了痴迷的标签。进入心流状态是一门科学。我想向你介绍两个概念。</p><p><strong>1) 史蒂芬·科特勒（Steven Kotler）的5大内在驱动力</strong></p><p>这5大内在驱动力分别是：好奇心、激情、使命感、自主权和精通。我们以前讨论过这个——但我想让你把注意力集中在“使命感（purpose）”这个驱动力上。</p><p>你通过追随自己的好奇心并在好奇心的交叉点上建立联系，来培养激情。当这些“交叉点”获得了现实世界中的实用价值时，使命感就诞生了。你想在这个世界上解决的一个重大问题是什么？你的好奇心如何能解决那个重大问题？不知道？太棒了，现在你有可以去研究的东西，有可以深入钻研的兔子洞了。</p><p>我的使命是终结人类的苦难。这在我内心点燃了一把火。我正在通过研究哲学、商业、灵性以及其他能让我传播自己理念的事物来践行这一点。我对这个非常痴迷。别人随口评头论足对我毫无意义，因为我能把注意力拉回到我的使命上。这是关键。</p><p><strong>2) 米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）的心流模型</strong></p><p>追随痴迷是有进阶过程的。它是挑战与技能之间的平衡。</p><p>你可以在任何时刻进入不同程度的心流状态。你需要一个期望的结果，清晰地知道如何达到那个结果，以及一个与你技能相匹配的挑战。</p><p><img src="'+r+'" alt=""></p><p>最优体验</p><p>如果你正在追求一个特定目标（期望结果），而这段旅程很无聊，你需要增加挑战难度。如果这段旅程让你感到焦虑，你需要提升你的技能。你可以通过互联网进行自我教育来做到这一点。</p><p>很快你就会明白这其中的道理。</p><p><strong>Koe Letter 读中插播广告</strong>：如果你想获取170多项关于社交媒体增长、变现、品牌建设、营销、销售以及绩效提升的策略——请加入MMHQ，与1000多名会员成为同路人。<a href="http://modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">Koe Letter 读者仅需5美元即可加入。</a></p><h2 id="在你想生活的世界里-创造你想玩的游戏" tabindex="-1">在你想生活的世界里，创造你想玩的游戏 <a class="header-anchor" href="#在你想生活的世界里-创造你想玩的游戏" aria-label="Permalink to &quot;在你想生活的世界里，创造你想玩的游戏&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>人生游戏</p><p>游戏是一个结构化的故事。这就是我们如此热爱游戏的原因。游戏为你提供了一种结构化的、以目标或任务为导向的方式，来实现期望的结果——也就是故事的完美结局。</p><p>如果你把一切都看作游戏，那一切都是游戏。游戏意味着规则、技能、挑战和里程碑。我们可以有意识地创造这些。这就是你预判痴迷，并给自己找一个值得专注的事物的方法。也就是说，找到一些值得你在乎的东西，这样你就可以不再去在乎那些无关紧要的破事了。</p><p>如果做得好，别人的看法、现代社会的干扰、个人的不安全感以及潜在的平庸就会不复存在。它们一开始之所以存在，仅仅是因为你把注意力给了它们。</p><p>人类是神圣的创作者。当我们进入最优体验、心流或活在当下时——我们就为创造腾出了空间。</p><p>让我们来创造属于自己的游戏：</p><h3 id="创造你的现实" tabindex="-1"><strong>创造你的现实</strong> <a class="header-anchor" href="#创造你的现实" aria-label="Permalink to &quot;**创造你的现实**&quot;">​</a></h3><p>作为人类，我们创造属于自己的现实。你的现实建立在你的视角与感知之上。这就是我们理解荒谬事物的方式。这一切都是把标签、符号、词语和解释串联成一个故事。它全都是虚构的——因为唯一存在的只有当下。心理时间——过去和未来——仅仅是你记住的故事的一部分。是你曾经有意识经历过的时间点。是那个时间点下，70亿分之一的你所拥有的视角。</p><p>如果你想让任何局面对你有利——就把你的视角切换到一个你可以对该局面产生优势感知的角度。视角是相机，感知是镜头。大多数人的相机架在三脚架上，镜头却是模糊的。他们不去移动相机，也不去擦亮镜头。这就导致了他们无法看清局势的本来面目。</p><p>假设你在一家熙熙攘攘的咖啡店里，看到一个很有吸引力的人。你的脑子会想到哪里去？我敢保证，它会出自一个对你毫无益处的错误视角。你的大脑会开始找借口。</p><p>“如果她拒绝了我，而且大家都注意到了怎么办？那太尴尬了。”</p><p>“如果她有男朋友了怎么办？我根本不该冒这个险。”</p><p>你能想到的每一个借口都会涌入脑海。察觉到这些想法，停下来，深呼吸，看清事情的本来面目。如果你去搭讪那个女孩，而她拒绝了你，这事儿就结束了。每个人都沉浸在自己小小现实里。他们过个5秒钟就不会在意了，而且你大概率再也不会见到他们。</p><p>这适用于任何事情。害怕面对镜头讲话并发到网上？最坏的情况能怎样？某个人在评论区骂你是个“弱智”？那个键盘侠难道没有他自己的一生要去过吗？</p><p>不要让一条评论成为你的整个世界。拉远镜头。获取全局视角。</p><h3 id="创造你的角色" tabindex="-1"><strong>创造你的角色</strong> <a class="header-anchor" href="#创造你的角色" aria-label="Permalink to &quot;**创造你的角色**&quot;">​</a></h3><blockquote><p>“我并非发生在我身上的事，我是我选择成为的人。” —— 卡尔·荣格（Carl Jung）</p></blockquote><p>在很多电子游戏中，你要做的第一件事就是创建角色。那个你想扮演的角色。那个<em>你</em>认为能把游戏玩得最好的角色。拿出一支笔和一张纸，事情到这里变得重要了。</p><p>根据我的经验，停止玩游戏的唯一方法就是赢得游戏。如果你想在社交媒体增长上获得初步成功——你需要遵守规则去玩这场游戏。一旦你有了足够的杠杆——一旦你达到满级——你就可以为所欲为。</p><ul><li>你的角色满级版本是什么样子的？</li><li>那个角色会培养出什么技能和特质？</li><li>那个角色会赚取多少金币？</li></ul><p>你对未来的愿景（期望结果）是什么？到达那里的步骤（目标和清晰度）有哪些？</p><h3 id="书写你的故事" tabindex="-1"><strong>书写你的故事</strong> <a class="header-anchor" href="#书写你的故事" aria-label="Permalink to &quot;**书写你的故事**&quot;">​</a></h3><p>生活在不同的章节和阶段中徐徐展开。</p><p>如果你想象有一部关于你人生的故事正在被书写，那么此刻正在写些什么？你正处于哪个章节？你是主角还是反派？你在打一场怎样的战役？你是站在赢的一方吗？这是从什么视角来写的？你是不是太在意要在咖啡店里约那个女孩出来了？如果是这样，你实现自我救赎了吗？</p><blockquote><p>“幸福就是感觉力量在增长——阻力正在被克服。”——尼采</p></blockquote><p>故事是我们创造生活意义的方式。意义存在于挣扎、战斗以及被克服的阻力之中。</p><p>你要为了赢而玩游戏吗？还是为了帮别人赢而玩？你要去追求属于你自己的角色主线吗？还是要在别人的故事线里当个NPC？这一切全在你掌控之中。</p><h3 id="赢得游戏" tabindex="-1">赢得游戏 <a class="header-anchor" href="#赢得游戏" aria-label="Permalink to &quot;赢得游戏&quot;">​</a></h3><p>万事万物皆是游戏。</p><p>社交媒体增长、在线业务、自信心、自我提升、技能获取等。一切皆是。</p><p>你通过学习规则、机制和原则来开始游戏。</p><p>你通过将注意力集中在内在的目标层级上来进行游戏。</p><p>你通过实现这些目标、获取经验值（XP），并将你角色渴望拥有的特质升到满级，从而赢得游戏。</p><p>对此别无他法。你要么玩游戏，要么被游戏玩。</p><p>你能停止游玩的唯一方式，就是你赢了。</p><p>—— Dan Koe</p><h3 id="本周动态" tabindex="-1">本周动态 <a class="header-anchor" href="#本周动态" aria-label="Permalink to &quot;本周动态&quot;">​</a></h3><p>Digital Economics（数字经济学）创始会员价现已上线——<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">仅剩11个名额。</a> 这是一个为期30天的强化训练营，旨在打造你的个人品牌，落地我的快速内容系统，并保障你在数字经济中的未来。</p><p>我们在MMHQ举办了一场内容心理学培训。这是一堂1.5小时的大师课，讲解如何捕获注意力、构建长短篇内容的结构，以及我的APAG文案框架——让你无需模板也能写出极具吸引力的内容。<a href="https://www.modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">Koe Letter的读者仅需5美元即可加入。</a></p><p>一期关于如何进入心流状态以及如何将你的好奇心转化为一门生意的播客现已上线。<a href="https://open.spotify.com/episode/7p8tPvPrwT6dhQfszvYJh8?si=85aaf8da89014e0a" target="_blank" rel="noreferrer">点击此处收听。</a></p><p>一期关于创意工作的未来以及如何通过追求你真正的好奇心来发家致富的YouTube视频刚刚上线。<a href="https://youtu.be/oNV08CLn6zI" target="_blank" rel="noreferrer">点击此处观看。</a></p><hr><p><a href="/en/letters/how-to-finally-stop-caring-what-other-people-think">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',79))])}const w=p(d,[["render",m]]);export{y as __pageData,w as default};
